<?php session_start();if(!isset($_SESSION['user'])){header('Location: login.php');exit;}require 'config/database.php';$cat=(int)($_GET['category']??0);$cs=$pdo->prepare('SELECT * FROM categories WHERE id=?');$cs->execute([$cat]);$category=$cs->fetch();if(!$category)die('Invalid category.');if(!isset($_SESSION['quiz'])||($_SESSION['quiz']['category']??0)!=$cat){$s=$pdo->prepare('SELECT * FROM questions WHERE category_id=? ORDER BY RAND() LIMIT 25');$s->execute([$cat]);$qs=$s->fetchAll();if(count($qs)<25)die('This category needs at least 25 questions in the database.');$_SESSION['quiz']=['category'=>$cat,'questions'=>$qs,'index'=>0,'score'=>0,'answers'=>[]];}$qz=&$_SESSION['quiz'];if($_SERVER['REQUEST_METHOD']==='POST'){ $q=$qz['questions'][$qz['index']];$ans=$_POST['answer']??'';$correct=$ans===$q['correct_answer'];if($correct)$qz['score']++;$qz['answers'][]=['question'=>$q['question'],'selected'=>$ans,'correct'=>$q['correct_answer'],'is_correct'=>$correct];$qz['index']++;if($qz['index']>=25){$s=$pdo->prepare('INSERT INTO quiz_results(user_id,category_id,score,total_questions) VALUES(?,?,?,25)');$s->execute([$_SESSION['user']['id'],$cat,$qz['score']]);$_SESSION['last_result']=$qz;unset($_SESSION['quiz']);header('Location: result.php');exit;}}$q=$qz['questions'][$qz['index']];$title=$category['name'].' Quiz';include 'includes/header.php';?>
<div class="row justify-content-center"><div class="col-lg-8"><div class="d-flex justify-content-between"><h2><?=htmlspecialchars($category['name'])?> Quiz</h2><strong>Question <?=$qz['index']+1?> / 25</strong></div><div class="progress mb-4"><div class="progress-bar bg-dark" style="width:<?=($qz['index']+1)*4?>%"></div></div><div class="card p-4"><h4><?=htmlspecialchars($q['question'])?></h4><?php if($q['code_snippet']):?><div class="code my-3"><?=htmlspecialchars($q['code_snippet'])?></div><?php endif;?><form method="post"><?php foreach(['A','B','C','D'] as $o): $f='option_'.strtolower($o);?><label class="choice"><input required type="radio" name="answer" value="<?=$o?>" class="me-2"> <strong><?=$o?>.</strong> <?=htmlspecialchars($q[$f])?></label><?php endforeach;?><button class="btn btn-dark mt-3"><?=$qz['index']==24?'Finish Quiz':'Next Question'?></button></form></div></div></div><?php include 'includes/footer.php';?>
